let idCounter = 1

export const MOCK_MENTIONS = rawMentions.map((m, idx) => {
  const platform = m.platform || randomFrom(platforms)
  const author = randomFrom(authors)
  const geo = randomFrom(countries)
  const daysAgo = m.daysAgo || randomBetween(1, 89)
  const hoursOffset = randomBetween(0, 23)
  const lang = m.lang || (geo === 'Malaysia' ? randomFrom(['en', 'ms', 'en', 'en']) : 'en')

  return {
    id: `mention-${String(idCounter++).padStart(4, '0')}`,
    text: m.text,
    platform,
    url: platformUrls[platform]?.(author.handle) || `https://example.com/${idx}`,
    author,
    publishedAt: seededDate(daysAgo, hoursOffset),
    keywordMatched: m.keywordMatched || [],
    keywordGroup: m.keywordGroup || 'corporate',
    sentiment: m.sentiment,
    emotions: m.emotions || [],
    engagement: platformEngagement[platform]?.() || { likes: 0, shares: 0, comments: 0, reach: 0 },
    geography: { country: geo, region: randomFrom(regions[geo] || ['Unknown']) },
    language: lang,
    mentionType: m.mentionType || 'news',
    riskFlag: m.riskFlag || false,
    riskLevel: m.riskLevel || null,
    topics: m.topics || [],
    isCompetitor: m.isCompetitor || false,
    analystReview: {
      reviewed: Math.random() > 0.7,
      overriddenSentiment: null,
      notes: '',
      assignedTo: Math.random() > 0.8 ? randomFrom(['analyst-1', 'analyst-2', 'analyst-3']) : null,
    },
    status: randomFrom(['new', 'new', 'new', 'reviewed', 'actioned', 'dismissed']),
  }
})
